-- Synthetic local fixture: database shapes only, auth stubs, no production data.
CREATE ROLE authenticated; CREATE ROLE anon; CREATE ROLE service_role BYPASSRLS;
CREATE SCHEMA auth; CREATE SCHEMA storage;
CREATE TABLE storage.buckets(id text PRIMARY KEY,name text,public boolean);
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
GRANT USAGE ON SCHEMA public,auth,storage TO authenticated,anon,service_role;
CREATE TABLE storage.objects(id uuid DEFAULT gen_random_uuid(),bucket_id text,name text);
ALTER TABLE storage.objects ENABLE ROW LEVEL SECURITY;
GRANT ALL ON storage.objects TO authenticated;
CREATE TABLE public.brands (id uuid NOT NULL DEFAULT gen_random_uuid(),group_id uuid,name text NOT NULL,slug text NOT NULL,color text DEFAULT '#D4A574'::text,active boolean DEFAULT true,created_at timestamp with time zone DEFAULT now());
