CREATE FUNCTION public.kph_is_founder() RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles u JOIN public.roles r ON r.id=u.role_id WHERE u.user_id=auth.uid() AND r.name='founder') $$;
CREATE FUNCTION public.kph_has_role_for_unit(p_unit_id uuid) RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT public.kph_is_founder() OR EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND unit_id=p_unit_id) $$;
GRANT SELECT ON public.user_roles, public.roles, public.units TO authenticated;


ALTER TABLE units ADD PRIMARY KEY(id);
CREATE UNIQUE INDEX dre_snapshot_pkey ON public.dre_snapshot USING btree (unit_id, competencia, conta_codigo);
